import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride_h, int stride_w,
                              int pad_h, int pad_w,
                              int dil_h, int dil_w);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int IC, int H, int Win,
    int OC, int KH, int KW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int Hout, int Wout)
{
  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int OcPerBlock = 4;

  const int tid = threadIdx.x;

  const int n       = blockIdx.z;
  const int oc_tile = blockIdx.y;
  const int oc_base = oc_tile * OcPerBlock;

  const int P_total = Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  // ---- Global tensors via CuTe ----
  const int64_t sXn = (int64_t)IC * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)OC * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(IC, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(OC, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );

  // Weight: [OC, IC, KH, KW]
  const int64_t sWoc = (int64_t)IC * KH * KW;
  const int64_t sWic = (int64_t)KH * KW;
  const int64_t sWkh = (int64_t)KW;

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(OC, IC, KH, KW),
      make_stride(sWoc, sWic, sWkh, Int<1>{})
  );

  // ---- Shared memory weight tile: (OcPerBlock, IC, KH, KW) ----
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);

  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<OcPerBlock>{}, IC, KH, KW),
      make_stride(sWic * (int64_t)KH == 0 ? 0 : (int64_t)IC * KH * KW, sWic, sWkh, Int<1>{})
  );

  const int total_w_elems = OcPerBlock * IC * KH * KW;
  const int per_oc = IC * KH * KW;
  const int per_ic = KH * KW;

  for (int idx = tid; idx < total_w_elems; idx += Threads) {
    int oc_local = idx / per_oc;
    int rem      = idx % per_oc;
    int ic       = rem / per_ic;
    int rem2     = rem % per_ic;
    int kh       = rem2 / KW;
    int kw       = rem2 % KW;
    int oc = oc_base + oc_local;

    T val = T(0);
    if (oc < OC) {
      val = mW(oc, ic, kh, kw);
    }
    sW(oc_local, ic, kh, kw) = val;
  }
  __syncthreads();

  // ---- Precompute per-thread output coordinates ----
  int p_idx[PVec];
  int oh_arr[PVec];
  int ow_arr[PVec];
  bool valid_p[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      oh_arr[i] = p / Wout;
      ow_arr[i] = p - oh_arr[i] * Wout;
      valid_p[i] = true;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
      valid_p[i] = false;
    }
  }

  // ---- Accumulators, init with bias ----
  float acc[OcPerBlock][PVec];
  #pragma unroll
  for (int oc_local = 0; oc_local < OcPerBlock; ++oc_local) {
    int oc = oc_base + oc_local;
    float bval = 0.0f;
    if (B != nullptr && oc < OC) {
      bval = (float)B[oc];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[oc_local][i] = bval;
    }
  }

  // ---- Main compute loop ----
  #pragma unroll 1
  for (int i = 0; i < PVec; ++i) {
    if (!valid_p[i]) continue;
    int oh = oh_arr[i];
    int ow = ow_arr[i];

    for (int kh = 0; kh < KH; ++kh) {
      int ih = oh * stride_h - pad_h + kh * dil_h;
      if ((unsigned)ih >= (unsigned)H) continue;

      for (int kw = 0; kw < KW; ++kw) {
        int iw = ow * stride_w - pad_w + kw * dil_w;
        if ((unsigned)iw >= (unsigned)Win) continue;

        #pragma unroll 1
        for (int ic = 0; ic < IC; ++ic) {
          float xval = (float)mX(ic, ih, iw);

          #pragma unroll
          for (int oc_local = 0; oc_local < OcPerBlock; ++oc_local) {
            float wval = (float)sW(oc_local, ic, kh, kw);
            acc[oc_local][i] += xval * wval;
          }
        }
      }
    }
  }

  // ---- Write results ----
  #pragma unroll
  for (int oc_local = 0; oc_local < OcPerBlock; ++oc_local) {
    int oc = oc_base + oc_local;
    if (oc >= OC) continue;

    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (!valid_p[i]) continue;
      mY(oc, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[oc_local][i]);
    }
  }
}

torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride_h, int stride_w,
                              int pad_h, int pad_w,
                              int dil_h, int dil_w) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [OC, IC, KH, KW]");

  int64_t N   = x.size(0);
  int64_t IC  = x.size(1);
  int64_t H   = x.size(2);
  int64_t Win = x.size(3);

  int64_t OC  = w.size(0);
  TORCH_CHECK(w.size(1) == IC, "w.size(1) must equal in_channels");
  int64_t KH  = w.size(2);
  int64_t KW  = w.size(3);

  TORCH_CHECK(stride_h > 0 && stride_w > 0, "stride must be > 0");
  TORCH_CHECK(dil_h > 0 && dil_w > 0, "dilation must be > 0");
  TORCH_CHECK(pad_h >= 0 && pad_w >= 0, "padding must be >= 0");

  int64_t Hout = (H + 2 * pad_h - dil_h * (KH - 1) - 1) / stride_h + 1;
  int64_t Wout = (Win + 2 * pad_w - dil_w * (KW - 1) - 1) / stride_w + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, Hout, Wout}, x.options());

  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int OcPerBlock = 4;

  const int64_t P_total = Hout * Wout;
  const int64_t PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((OC + OcPerBlock - 1) / OcPerBlock),
      (unsigned)N
  );

  size_t smem_bytes = (size_t)OcPerBlock * (size_t)IC * (size_t)KH * (size_t)KW * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  if (smem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(conv2d_kernel<float>,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)smem_bytes);
  }

  conv2d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)IC, (int)H, (int)Win,
      (int)OC, (int)KH, (int)KW,
      stride_h, stride_w,
      pad_h, pad_w,
      dil_h, dil_w,
      (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 2D convolution with asymmetric kernel, padding, and dilation,
    implemented with a single custom CUDA kernel using CuTe.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: int = 1, padding: tuple = (0, 0), dilation: tuple = (1, 1),
                 bias: bool = False) -> None:
        super().__init__()

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = (int(kernel_size[0]), int(kernel_size[1]))
        self.stride = (int(stride), int(stride))
        self.padding = (int(padding[0]), int(padding[1]))
        self.dilation = (int(dilation[0]), int(dilation[1]))

        KH, KW = self.kernel_size
        self.weight = nn.Parameter(torch.empty(self.out_channels, self.in_channels, KH, KW))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size[0] * self.kernel_size[1]
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            self.stride[0], self.stride[1],
            self.padding[0], self.padding[1],
            self.dilation[0], self.dilation[1],
        )

