#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int IC, int H, int Win,
    int OC, int KH, int KW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int Hout, int Wout)
{
  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int OcPerBlock = 4;

  const int tid = threadIdx.x;

  const int n       = blockIdx.z;
  const int oc_tile = blockIdx.y;
  const int oc_base = oc_tile * OcPerBlock;

  const int P_total = Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  // ---- Global tensors via CuTe ----
  const int64_t sXn = (int64_t)IC * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)OC * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(IC, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(OC, Hout, Wout),
      make_stride(sYc, sYh, Int<1>{})
  );

  // Weight: [OC, IC, KH, KW]
  const int64_t sWoc = (int64_t)IC * KH * KW;
  const int64_t sWic = (int64_t)KH * KW;
  const int64_t sWkh = (int64_t)KW;

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(OC, IC, KH, KW),
      make_stride(sWoc, sWic, sWkh, Int<1>{})
  );

  // ---- Shared memory weight tile: (OcPerBlock, IC, KH, KW) ----
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);

  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<OcPerBlock>{}, IC, KH, KW),
      make_stride(sWic * (int64_t)KH == 0 ? 0 : (int64_t)IC * KH * KW, sWic, sWkh, Int<1>{})
  );

  const int total_w_elems = OcPerBlock * IC * KH * KW;
  const int per_oc = IC * KH * KW;
  const int per_ic = KH * KW;

  for (int idx = tid; idx < total_w_elems; idx += Threads) {
    int oc_local = idx / per_oc;
    int rem      = idx % per_oc;
    int ic       = rem / per_ic;
    int rem2     = rem % per_ic;
    int kh       = rem2 / KW;
    int kw       = rem2 % KW;
    int oc = oc_base + oc_local;

    T val = T(0);
    if (oc < OC) {
      val = mW(oc, ic, kh, kw);
    }
    sW(oc_local, ic, kh, kw) = val;
  }
  __syncthreads();

  // ---- Precompute per-thread output coordinates ----
  int p_idx[PVec];
  int oh_arr[PVec];
  int ow_arr[PVec];
  bool valid_p[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      oh_arr[i] = p / Wout;
      ow_arr[i] = p - oh_arr[i] * Wout;
      valid_p[i] = true;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
      valid_p[i] = false;
    }
  }

  // ---- Accumulators, init with bias ----
  float acc[OcPerBlock][PVec];
  #pragma unroll
  for (int oc_local = 0; oc_local < OcPerBlock; ++oc_local) {
    int oc = oc_base + oc_local;
    float bval = 0.0f;
    if (B != nullptr && oc < OC) {
      bval = (float)B[oc];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[oc_local][i] = bval;
    }
  }

  // ---- Main compute loop ----
  #pragma unroll 1
  for (int i = 0; i < PVec; ++i) {
    if (!valid_p[i]) continue;
    int oh = oh_arr[i];
    int ow = ow_arr[i];

    for (int kh = 0; kh < KH; ++kh) {
      int ih = oh * stride_h - pad_h + kh * dil_h;
      if ((unsigned)ih >= (unsigned)H) continue;

      for (int kw = 0; kw < KW; ++kw) {
        int iw = ow * stride_w - pad_w + kw * dil_w;
        if ((unsigned)iw >= (unsigned)Win) continue;

        #pragma unroll 1
        for (int ic = 0; ic < IC; ++ic) {
          float xval = (float)mX(ic, ih, iw);

          #pragma unroll
          for (int oc_local = 0; oc_local < OcPerBlock; ++oc_local) {
            float wval = (float)sW(oc_local, ic, kh, kw);
            acc[oc_local][i] += xval * wval;
          }
        }
